const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat /workspace/instruction.md",max_output_tokens:8000}),
  tools.exec_command({cmd:"cat /tmp/research_notes.md",max_output_tokens:12000}),
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g 'method.py' -g 'solve.sh' -g '*.md' /workspace/solution /workspace/environment/public_assets",max_output_tokens:8000}),
  tools.exec_command({cmd:"ls -la /tmp/research_history",max_output_tokens:5000})
]); results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
 tools.exec_command({cmd:"cat method.py",max_output_tokens:16000}),
 tools.exec_command({cmd:"cat solve.sh && rg --files /workspace/environment/public_assets && cat /tmp/research_history/screen_all.py && cat /tmp/research_history/fresh_bench.py",max_output_tokens:8000}),
 tools.exec_command({cmd:"cat /tmp/research_history/000_baseline/method.py",max_output_tokens:16000}),
 tools.exec_command({cmd:"rg --files -g 'AGENTS.md' /workspace /tmp/research_history; cat /tmp/research_history/episode_5_working_notes.md",max_output_tokens:10000})
]); results.forEach((r,i)=>text({i,...r}));

const results=await Promise.allSettled([
tools.exec_command({cmd:"cat /tmp/research_history/build_episode5_moments.py && cat /tmp/research_history/build_episode5_classmean.py && cat /tmp/research_history/profile_episode5.py",max_output_tokens:7000}),
tools.exec_command({cmd:"tail -c 2000 /tmp/research_history/266_start265_repeat/evaluator.log && rg --files /tmp/research_history | rg 'sparse|active|moment|classmean|265|264'",max_output_tokens:4000})
]);results.forEach((r,i)=>text({i,...r}));

const results=await Promise.allSettled([
tools.exec_command({cmd:"cat /tmp/research_history/profile_episode5.py && rg --files /tmp/research_history | rg 'build_episode5|bench_episode5'",max_output_tokens:4000}),
tools.exec_command({cmd:"cat /tmp/research_history/052_active_edges_late_final/method.py && cat /tmp/research_history/199_moment1_initial_fused/method.py",max_output_tokens:14000}),
tools.exec_command({cmd:"cat /tmp/research_history/episode5_official_summary.json",max_output_tokens:3000})
]);results.forEach((r,i)=>text({i,...r}));

const results=await Promise.allSettled([
 tools.exec_command({cmd:"cat /tmp/research_history/129_packed_class_geometry/method.py && cat /tmp/research_history/build_episode5_class_truncation.py && cat /tmp/research_history/build_episode5_class_initial.py",max_output_tokens:13000}),
 tools.exec_command({cmd:"cat /tmp/research_history/266_start265_repeat/evaluator.log",max_output_tokens:3000})
]);results.forEach((r,i)=>text({i,...r}));

