from pathlib import Path
root=Path('/tmp/research_history');base=(root/'162_precomputed_norm_geometry/method.py').read_text()
point=('R*=(-1./eps)\n        R.clamp_(min=-80.).mul_(1.4426950408889634).exp2_()', 'R.mul_(-1.4426950408889634/eps).exp2_()')
cls=('K=R.sub_(rm[:,None,None]).div_(eps[:,None,None]).neg_().clamp_(min=-80.).mul_(1.4426950408889634).exp2_()\n        K.masked_fill_(~valid,0.)','K=R.sub_(rm[:,None,None]).mul_((-1.4426950408889634/eps)[:,None,None]).exp2_()')
for scope,name in [('point','188_fuse_direct_point'),('class','189_fuse_direct_class'),('both','190_fuse_direct_both')]:
 s=base
 if scope in ('point','both'):s=s.replace(*point)
 if scope in ('class','both'):s=s.replace(*cls)
 s=s.replace('K=(C/(-.1*float(C.max()))).mul_(1.4426950408889634).exp2_()', 'K=(C*(-14.426950408889634/float(C.max()))).exp2_()')
 p=root/name;p.mkdir(exist_ok=True);(p/'method.py').write_text(s)
with (root/'episode_5_working_notes.md').open('a') as f:f.write('\n188-190 fuse all direct-kernel exponent scale constants, remove negligible tiny-tail clamp and redundant padded mask (inf distances exponentiate tozero), with stable fallback retained. Point/class/both ablations plus scalar fused coupling scale. Saves dense memory passes without changing intended operator. Not screened yet.\n')
"}

